//! Conformance P32: cross-language canonical replay and standards-migration qualification.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;pub const CONTENT_TYPE:&str="application/vnd.aurora.conformance.replay-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReplayCase4{pub case_id:String,pub language:String,pub runtime_version:String,pub schema_version:String,pub expected_digest:String,pub observed_digest:String,pub canonical_bytes:String,pub standards:Vec<String>,pub migration_loss_declared:bool,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReplayIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub cases:Vec<ReplayCase4>,pub required_case_order:Vec<String>,pub required_language_order:Vec<String>,pub replay_identity:String,pub standards_epoch:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub case_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReplayIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReplayIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub case_order:Vec<String>,pub parity_order:Vec<String>,pub mismatch_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub language_order:Vec<String>,pub standards_order:Vec<String>,pub migration_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:ReplayIntegrityArtifact4}
#[derive(Debug,Error)] pub enum ReplayIntegrityError{#[error("replay integrity input is invalid: {0}")] Invalid(String),#[error("replay integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->ReplayIntegrityError{ReplayIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"conformance","consumers":["release gate","SDK parity harness","workflow replay auditor","standards registry"],"behavior":format!("qualify byte-identical cross-language replay at {scale} ({mode})"),"value":"prevents semantic drift, stale standards, and mismatched replay artifacts from releasing","input_schema":"ReplayIntegrityRequest4@1","output_schema":"ReplayIntegrityCard7@1","effects":["emit:replay-card","retain:parity-witness","block:semantic-drift"],"permissions":["read:local-fixtures"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&ReplayIntegrityCard7)->Result<(),ReplayIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("replay identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.case_order,&c.parity_order,&c.mismatch_order,&c.unknown_order,&c.omitted_order,&c.language_order,&c.standards_order,&c.migration_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("replay vectors are not canonical"));}}let ids=c.case_order.iter().collect::<BTreeSet<_>>();let states=c.parity_order.iter().chain(&c.mismatch_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("case states do not partition cases"));}Ok(())}
pub fn qualify(q:&ReplayIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<ReplayIntegrityCard7,ReplayIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.cases.is_empty()||q.required_case_order.is_empty()||!canonical(&q.required_case_order)||!canonical(&q.required_language_order)||q.standards_epoch.trim().is_empty()||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.case_budget==0{return Err(invalid("replay identity, ordering, standards, locality, boundary, or budget is invalid"));}let mut rows=q.cases.clone();rows.sort_by(|a,b|a.case_id.cmp(&b.case_id));let mut seen=BTreeSet::new();let mut parity=BTreeSet::new();let mut mismatch=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut languages=BTreeSet::new();let mut standards=BTreeSet::new();let mut migrations=BTreeSet::new();let mut evidence=BTreeSet::new();for c in &rows{if c.case_id.trim().is_empty()||!seen.insert(c.case_id.clone())||c.language.trim().is_empty()||c.runtime_version.trim().is_empty()||c.schema_version.trim().is_empty()||!digest(&c.expected_digest)||!digest(&c.observed_digest)||c.canonical_bytes.trim().is_empty()||c.evidence_state.trim().is_empty()||!c.local||!c.aggregate_only{return Err(invalid("case identity, digest, bytes, evidence, or locality is invalid"));}languages.insert(format!("{}:{}",c.case_id,c.language));standards.extend(c.standards.iter().map(|x|format!("{}:{}",c.case_id,x)));if c.migration_loss_declared{migrations.insert(format!("{}:declared-loss",c.case_id));}evidence.insert(c.expected_digest.clone());if c.evidence_state=="unknown"||c.expected_digest==q.replay_identity{unknown.insert(c.case_id.clone());}else if c.expected_digest!=c.observed_digest||c.canonical_bytes!="canonical"{mismatch.insert(c.case_id.clone());}else if !q.required_case_order.contains(&c.case_id){omitted.insert(c.case_id.clone());}else{parity.insert(c.case_id.clone());}}let missing=q.required_case_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_approval||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.case_budget;if global{omitted.extend(seen.iter().cloned());parity.clear();mismatch.clear();unknown.clear();}let complete=missing.is_empty();let disposition=if global{"blocked"}else if !complete||!unknown.is_empty(){"unknown"}else if !mismatch.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let case_order=seen.iter().cloned().collect::<Vec<_>>();let parity_order=parity.into_iter().collect::<Vec<_>>();let mismatch_order=mismatch.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"case_order":case_order,"parity_order":parity_order,"mismatch_order":mismatch_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"language_order":languages.into_iter().collect::<Vec<_>>(),"standards_order":standards.into_iter().collect::<Vec<_>>(),"migration_order":migrations.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|ReplayIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:replay:{}",q.request_id)]}else{vec!["block:semantic-drift".into()]};let artifact=ReplayIntegrityArtifact4{artifact_id:format!("conformance-replay:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=ReplayIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),case_order:body["case_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),parity_order,mismatch_order,unknown_order,omitted_order,language_order:body["language_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),standards_order:body["standards_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),migration_order:body["migration_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
